	// Set the REST API tracking endpoint URL.
					wcAnalytics.trackEndpoint = "https://axiomsystems.systems/wp-json/woocommerce-analytics/v1/track";

	// Set common properties for all events.
	wcAnalytics.commonProps = {"ui":0,"blog_id":251700914,"store_id":"f5a23b9f-6114-4602-bea6-e4a8932be5c4","url":"https://axiomsystems.systems","woo_version":"11.2.1","wp_version":"7.1.3","store_admin":0,"device":"desktop","store_currency":"USD","timezone":"+00:00","is_guest":1,"package_version":"0.18.0"};

	// Set the event queue.
	wcAnalytics.eventQueue = [];

	// Features.
	wcAnalytics.features = {
		ch: false,
		sessionTracking: false,
		proxy: false,
	};

	wcAnalytics.breadcrumbs = ["Error 404"];

